const CPS = 3.5;
const MIN_DELAY = 6;
const MAX_DELAY = 30;

for (const item of items) {

  const mensagem = item.json.output || item.json.message || "";
  const tamanho = mensagem.length;

  let tempoBase = tamanho / CPS;

  // Mensagem curta evita padrão 5s
  if (tamanho < 40) {
    tempoBase = 6 + Math.random() * 9; // 6 a 15
  }

  // variação base
  const variacao = tempoBase * (Math.random() * 0.4 - 0.15);
  let tempoFinal = tempoBase + variacao;

  // 🔥 EXTRA HUMANO
  const r = Math.random();

  if (r < 0.20) {
    // 20% das vezes adiciona +5 a +20 segundos
    tempoFinal += 5 + Math.random() * 15;
  } else if (r < 0.30) {
    // 10% das vezes adiciona +20 a +40 segundos
    tempoFinal += 20 + Math.random() * 20;
  }

  tempoFinal = Math.max(MIN_DELAY, Math.min(MAX_DELAY, tempoFinal));
  tempoFinal = Math.round(tempoFinal);

  item.json.delaySeconds = tempoFinal;
  item.json.delayMs = tempoFinal * 1000;
  item.json.delayHuman = `${tempoFinal}s`;
}

return items;

