const now = new Date();
const results = [];

for (const item of items) {
  const start = new Date(item.json.start.dateTime || item.json.start.date);
  const diffMs = start - now;
  const diffMinutes = diffMs / 60000;

  // Salva no JSON do item
  item.json.diffMinutes = diffMinutes;
  results.push(item);
}

return results;
